{"path":"internal/app/ui/rendering.go","content":"package ui

import (
	"context"
	"fmt"
	"strings"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"

	"idiom/internal/llama"
)

// RenderedView describes the full TUI output for one frame.
type RenderedView struct {
	Content string
}

// RenderView builds the full TUI view string from the model state.
func RenderView(m *ModelState, mdRenderer interface{ Render(string) (string, error) }) string {
	if !m.Ready {
		return "Loading UI..."
	}

	w := maxInt(0, m.Width)

	// ── Header ────────────────────────────────────────────────────────────────
	serverState := "down"
	if m.ServerUp {
		serverState = "up"
	}
	if m.BootingServer {
		serverState = m.SpinnerView() + " booting"
	}
	leftTitle := titleStyle.Render("◆ " + m.AppName)
	rightInfo := statusStyle.Render(serverState + "  " + fallback(m.ModelID, "unknown"))
	headerGap := w - lipgloss.Width(leftTitle) - lipgloss.Width(rightInfo)
	if headerGap < 0 {
		headerGap = 0
	}
	header := leftTitle + strings.Repeat(" ", headerGap) + rightInfo

	divider := dividerStyle.Render(strings.Repeat("─", w))

	// ── Footer ────────────────────────────────────────────────────────────────
	var footerLines []string

	if pending := m.CurrentApproval(); pending != nil {
		footerLines = append(footerLines,
			approvalStyle.Width(w).Render("▲  APPROVAL REQUIRED ("+pending.Mode+"):  "+pending.Summary()+"  →  /approve or /deny"))
	}

	if banner := m.ErrorBanner(); banner != "" {
		footerLines = append(footerLines, errorStyle.Render(banner))
	}

	// Compact status bar: context info left, status + char count right.
	infoLeft := contextStyle.Render(
		"mode: " + m.ModeSummary() + "  ·  trace: " + m.TraceSummary() +
			"  ·  ctx: " + m.ContextSummary() + "  ·  " + m.WorkspaceSummary())
	var rightParts []string
	if m.Status != "" {
		rightParts = append(rightParts, m.Status)
	}
	if n := len([]rune(m.InputValue())); n > 0 {
		rightParts = append(rightParts, fmt.Sprintf("%d", n))
	}
	infoRight := statusStyle.Render(strings.Join(rightParts, "  ·  "))
	barGap := w - lipgloss.Width(infoLeft) - lipgloss.Width(infoRight)
	if barGap < 1 {
		barGap = 1
	}
	footerLines = append(footerLines, infoLeft+strings.Repeat(" ", barGap)+infoRight)

	footer := strings.Join(footerLines, "\n")

	// ── Content row: main viewport + optional side panel (tabbed) ────────────
	var contentRow string
	if m.HistoryPanelOpen {
		h := m.Viewport.Height
		vertBar := dividerStyle.Render(strings.Repeat("│\n", h-1) + "│")
		panelWidth := m.HistoryViewport.Width
		activeVP := activePanelViewport(m)
		panel := lipgloss.JoinVertical(lipgloss.Left,
			renderPanelTabs(panelWidth, m),
			activeVP.View(),
		)
		contentRow = lipgloss.JoinHorizontal(lipgloss.Top,
			m.Viewport.View(),
			vertBar,
			panel,
		)
	} else {
		contentRow = m.Viewport.View()
	}

	return lipgloss.JoinVertical(lipgloss.Left, header, divider, contentRow, divider, m.InputView(), footer)
}

// BuildRequestMessages assembles the chat messages for the next model request.
func BuildRequestMessages(m *ModelState, systemPromptFn func() string, compactFn func(context.Context, []llama.ChatMessage) []llama.ChatMessage, pinnedSnapshotFn func() string) []llama.ChatMessage {
	var messages []llama.ChatMessage
	if prompt := strings.TrimSpace(systemPromptFn()); prompt != "" {
		messages = append(messages, llama.ChatMessage{Role: "system", Content: prompt})
	}
	// OpenCode-aligned: no static workspace-overview injection. The model
	// discovers the layout by calling list_files / glob / search tools on
	// demand, exactly like it does in OpenCode. Injecting a static tree
	// every turn inflated prompt tokens and taught the model that the
	// harness always pre-answers orientation questions — which trained it
	// to skip real discovery.
	history := m.Messages
	if len(history) > 0 {
		last := history[len(history)-1]
		if last.Role == "assistant" && last.Content == "" {
			history = history[:len(history)-1]
		}
	}
	// Fix 5 (context compaction) — fold the oldest messages into a session
	// digest before the hard-truncation below kicks in.
	history = compactFn(context.Background(), history)

	// Pinned-file reference snapshot — keep recently-read files visible even
	// after their raw tool results have been compacted out of history.
	if snapshot := pinnedSnapshotFn(); snapshot != "" {
		messages = append(messages, llama.ChatMessage{Role: "system", Content: snapshot})
	}

	start := 0
	if limit := m.MaxHistory; limit > 0 && len(history) > limit {
		start = len(history) - limit
	}
	for _, msg := range history[start:] {
		messages = append(messages, llama.ChatMessage{
			Role:             normalizeHistoryRole(msg.Role),
			Content:          msg.Content,
			ReasoningContent: msg.ReasoningContent,
		})
	}
	return messages
}

// RenderMessages updates the viewport with the current message history.
func RenderMessages(m *ModelState, mdRenderer interface{ Render(string) (string, error) }, forceBottom bool) {
	if !m.Ready {
		return
	}

	stickBottom := forceBottom || m.Viewport.AtBottom()

	msgBodyStyle := bodyStyle.Width(maxInt(1, m.Viewport.Width))

	var b strings.Builder
	for _, msg := range m.Messages {
		var label string
		useGlamour := false
		content := strings.TrimSpace(msg.Content)
		switch msg.Role {
		case "user":
			label = userLabelStyle.Render("You")
		case "assistant":
			label = assistantLabelStyle.Render("Qwen")
			if content != "" {
				useGlamour = true
			}
		case "tool":
			// Surface the tool name from the first line: "tool_name | summary..."
			toolName := "tool"
			if idx := strings.Index(content, " | "); idx > 0 {
				toolName = content[:idx]
			} else if fields := strings.Fields(content); len(fields) > 0 {
				toolName = fields[0]
			}
			label = toolLabelStyle.Render("▶ " + toolName)
		default:
			label = systemLabelStyle.Render(strings.Title(msg.Role))
		}
		b.WriteString(label)
		b.WriteString("\n")
		if useGlamour && mdRenderer != nil {
			rendered, err := mdRenderer.Render(content)
			if err == nil {
				b.WriteString(strings.TrimRight(rendered, "\n"))
			} else {
				b.WriteString(msgBodyStyle.Render(content))
			}
		} else {
			b.WriteString(msgBodyStyle.Render(content))
		}
		b.WriteString("\n\n")
	}

	// While a turn is in flight, render a live "Qwen is working" affordance
	// after the last message. The in-flight reply is NOT kept in m.messages
	// as an empty placeholder (that caused double-rendering via the reply
	// bookkeeping path); we draw the spinner inline instead.
	if m.Streaming {
		label := assistantLabelStyle.Render("Qwen")
		content := m.SpinnerView() + " Qwen is working on your request" + workingDots(m)
		b.WriteString(label)
		b.WriteString("\n")
		b.WriteString(msgBodyStyle.Render(content))
		b.WriteString("\n\n")
	}

	if len(m.Messages) == 0 && !m.Streaming {
		b.WriteString(msgBodyStyle.Render("No messages yet. Type a prompt below or use /help."))
	}

	m.Viewport.SetContent(strings.TrimRight(b.String(), "\n"))
	if stickBottom {
		m.Viewport.GotoBottom()
	}
}

// UpdateViewport processes a tea.Msg through the viewport's Update method.
func UpdateViewport(m *ModelState, msg tea.Msg) {
	if !m.Ready {
		return
	}
	var cmd tea.Cmd
	m.Viewport, cmd = m.Viewport.Update(msg)
	_ = cmd
}

// ScrollableViewportKey reports whether msg is a viewport-scrolling key.
func ScrollableViewportKey(msg tea.Msg) bool {
	keyMsg, ok := msg.(tea.KeyMsg)
	if !ok {
		return false
	}
	switch keyMsg.Type {
	case tea.KeyPgUp, tea.KeyPgDown:
		return true
	default:
		return false
	}
}

// Helper functions that need access to model state

func activePanelViewport(m *ModelState) interface{ View() string } {
	switch m.PanelTab {
	default:
		return m.HistoryViewport
	}
}

func renderPanelTabs(width int, m *ModelState) string {
	var b strings.Builder
	tabs := []struct {
		label string
		tab   int
		style interface{ Render(string) string
	}{
		{"History", 0, panelTabInactiveStyle},
		{"Sessions", 1, panelTabInactiveStyle},
		{"Plan", 2, panelTabInactiveStyle},
	}
	for i, t := range tabs {
		if i == m.PanelTab {
			b.WriteString(t.panelTabActiveStyle.Render(t.label))
		} else {
			b.WriteString(t.panelTabInactiveStyle.Render(t.label))
		}
		if i < len(tabs)-1 {
			b.WriteString("  ")
		}
	}
	return b.String()
}

func workingDots(m *ModelState) string {
	dots := "..."
	return dots
}
