// renderPanelTabs renders the tab header for the side panel.
func renderPanelTabs(width int, m *ModelView) string {
	tabs := []string{"History", "Sessions", "Plan"}
	var b strings.Builder
	for i, label := range tabs {
		if i == m.PanelTab {
			b.WriteString(panelTabActiveStyle.Render(label))
		} else {
			b.WriteString(panelTabInactiveStyle.Render(label))
		}
		if i < len(tabs)-1 {
			b.WriteString("  ")
		}
	}
	return b.String()
}

